head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setFocusedMultiCell]<br/>Row 와 Column 의 인덱스를 사용하여 특정 영역의 Cell 을 포커스 상태로 설정합니다.",
    "validation" : [
        "startRowIdx(필수) 파라미터로 포커스 상태로 설정할 영역의 시작 Row 인덱스를 설정합니다.",
        "startColIdx(필수) 파라미터로 포커스 상태로 설정할 영역의 시작 Column 인덱스를 설정합니다.",
        "endRowIdx(필수) 파라미터로 포커스 상태로 설정할 영역의 종료 Row 인덱스를 설정합니다.",
        "endColIdx(필수) 파라미터로 포커스 상태로 설정할 영역의 종료 Column 인덱스를 설정합니다.",
        "설정한 영역의 Cell 이 포커스 상태로 설정되어야 합니다.",
        "파라미터 영역의 경계에 병합된 Cell 의 일부가 포함된 경우 병합 Cell 의 영역까지 포커스 되어야 합니다.",
        "숨겨진 Column 도 포함 하여 인덱스가 설정되어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // dataList 생성
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성 (숨겨진 Column 포함)
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" useShiftKey="true" checkAllType="false" id="" style="width:500px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column1" value="name1"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column2" value="name2(H)" hidden="true"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col2" hidden="true" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 셀 병합
    target1.mergeCell({"rowIndex" : 0, "colIndex" : 2, "colSpan" : 2, "rowSpan" : 2});
}



scwin.btn_setFocusedMultiCell_onclick = function () {
    let startRowIdx = Number(par_startRowIdx.getText());
    let startColIdx = Number(par_startColIdx.getText());
    let endRowIdx = Number(par_endRowIdx.getText());
    let endColIdx = Number(par_endColIdx.getText());

    target1.setFocusedMultiCell(startRowIdx, startColIdx, endRowIdx, endColIdx);

    wf_body_bottom.getObj("scwin").setReturnValue("setFocusedMultiCell(" + startRowIdx + ", " + startColIdx + ", " + endRowIdx + ", " + endColIdx + ")");

    // 포커스 영역 확인
    let allFocused = target1.getAllFocusedIndex();
    wf_body_bottom.getObj("scwin").setReturnValue("getAllFocusedIndex : " + JSON.stringify(allFocused));
}
